-- Current-installed service_role ACL hardening only. Production execution is NOT authorized.
-- External exact classifier also pins real Production function/data fingerprints.
-- Future canonical exam INSERT/INSERT/UPDATE privileges are deliberately excluded.
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';
do $current_service_transition$
declare
  browser jsonb;
  service jsonb;
  identity_state jsonb;
  adoption_state jsonb;
  catalog_before text;
  browser_before jsonb;
  boundary_before jsonb;
begin
  if current_user <> 'postgres' or current_setting('server_version_num')::integer not between 170000 and 179999 then
    raise exception 'Managed postgres on PG17 required' using errcode='55000';
  end if;
  select (
  with expected(table_name) as (select unnest(array['user_profiles','match_preparations','post_match_reviews','psychology_checkins','psychology_wellbeing_assessments','psychology_exercise_sessions','attempts','exam_results','rules_exam_results','notification_events','user_global_roles','user_subscriptions','referee_exam_sessions']::text[])),
  relations as (
    select c.* from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace
    where n.nspname='public' and c.relname in ('user_profiles','match_preparations','post_match_reviews','psychology_checkins','psychology_wellbeing_assessments','psychology_exercise_sessions','attempts','exam_results','rules_exam_results','notification_events','user_global_roles','user_subscriptions','referee_exam_sessions') and c.relkind in ('r','p')
  ), columns as (
    select c.relname as table_name,c.oid as table_oid,a.* from relations c
    join pg_catalog.pg_attribute a on a.attrelid=c.oid where a.attnum>0 and not a.attisdropped
  ), table_acl as (
    select c.relname as table_name,a.* from relations c
    cross join lateral pg_catalog.aclexplode(coalesce(c.relacl,pg_catalog.acldefault('r',c.relowner))) a
  ), column_acl as (
    select c.table_name,c.attname,a.* from columns c cross join lateral pg_catalog.aclexplode(c.attacl) a
  ), policies as (
    select c.relname as table_name,p.* from relations c join pg_catalog.pg_policy p on p.polrelid=c.oid
  )
  select pg_catalog.jsonb_build_object(
    'tables',(select jsonb_agg(jsonb_build_object('schema','public','table',e.table_name,
      'exists',c.oid is not null,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force',c.relforcerowsecurity,
      'installer_authority',case when c.oid is null then null else
        c.relowner=(select oid from pg_roles where rolname=current_user) or pg_has_role(current_user,c.relowner,'USAGE') end,
      'raw_acl',c.relacl,'acl_origin',case when c.relacl is null then 'DEFAULT_OWNER_ACL' else 'EXPLICIT_ACL' end)
      order by e.table_name) from expected e left join relations c on c.relname=e.table_name),
    'tableAcls',(select coalesce(jsonb_agg(jsonb_build_object('schema','public','table',table_name,
      'grantee',case when grantee=0 then 'PUBLIC' else pg_get_userbyid(grantee) end,
      'grantor',pg_get_userbyid(grantor),'privilege',privilege_type,'grantable',is_grantable)
      order by table_name,grantee,grantor,privilege_type),'[]'::jsonb) from table_acl),
    'columnAcls',(select coalesce(jsonb_agg(jsonb_build_object('schema','public','table',table_name,'column',attname,
      'grantee',case when grantee=0 then 'PUBLIC' else pg_get_userbyid(grantee) end,
      'grantor',pg_get_userbyid(grantor),'privilege',privilege_type,'grantable',is_grantable)
      order by table_name,attname,grantee,grantor,privilege_type),'[]'::jsonb) from column_acl),
    'columns',(select coalesce(jsonb_agg(jsonb_build_object('schema','public','table',table_name,'column',attname,
      'raw_acl',attacl) order by table_name,attnum),'[]'::jsonb) from columns),
    'effectiveBrowserPrivileges',(select coalesce(jsonb_agg(jsonb_build_object('schema','public','table',c.relname,
      'role',r.rolname,'privilege',p.privilege,'granted',pg_catalog.has_table_privilege(r.oid,c.oid,p.privilege))
      order by c.relname,r.rolname,p.privilege),'[]'::jsonb) from relations c
      cross join pg_catalog.pg_roles r cross join unnest(array['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER','MAINTAIN']) p(privilege)
      where r.rolname in ('anon','authenticated')),
    'effectiveBrowserColumnPrivileges',(select coalesce(jsonb_agg(jsonb_build_object('schema','public','table',c.table_name,
      'column',c.attname,'role',r.rolname,'privilege',p.privilege,
      'granted',pg_catalog.has_column_privilege(r.oid,c.table_oid,c.attnum,p.privilege))
      order by c.table_name,c.attname,r.rolname,p.privilege),'[]'::jsonb) from columns c
      cross join pg_catalog.pg_roles r cross join unnest(array['SELECT','INSERT','UPDATE','REFERENCES']) p(privilege)
      where r.rolname in ('anon','authenticated')),
    'policies',(select coalesce(jsonb_agg(jsonb_build_object('schema','public','table',table_name,'oid',oid,
      'name',polname,'command',case polcmd when 'r' then 'SELECT' when 'a' then 'INSERT'
        when 'w' then 'UPDATE' when 'd' then 'DELETE' else 'ALL' end,'permissive',polpermissive,
      'roles',(select jsonb_agg(case when role_oid=0 then 'PUBLIC' else pg_get_userbyid(role_oid) end order by role_oid)
        from unnest(polroles) role_oid),'using',pg_catalog.pg_get_expr(polqual,polrelid,false),
      'withCheck',pg_catalog.pg_get_expr(polwithcheck,polrelid,false)) order by table_name,polname),'[]'::jsonb) from policies),
    'catalogCounts',jsonb_build_object('tableAcls',(select count(*) from table_acl),
      'columnAcls',(select count(*) from column_acl),'columns',(select count(*) from columns),
      'policies',(select count(*) from policies))
  )
) into browser;
  select (
 with expected(table_name) as (select unnest(array['user_profiles','match_preparations','post_match_reviews','psychology_checkins','psychology_wellbeing_assessments','psychology_exercise_sessions','attempts','exam_results','rules_exam_results','notification_events','user_global_roles','user_subscriptions','referee_exam_sessions','capabilities','capability_overrides','plan_capabilities','institutions','institution_subscriptions','institution_permissions','institution_roles','institution_role_permissions','institution_membership_permission_overrides','institution_memberships','institution_membership_roles','institution_groups','institution_group_memberships','institution_cohorts','institution_contents','institution_content_assignments','institution_assessments','institution_assessment_items','institution_assessment_assignments','institution_assessment_sessions','institution_assessment_history','institution_notification_campaigns','institution_notification_recipients','institution_demo_sessions','institution_data_consents','countries','associations','competitions','competition_seasons','competition_categories','teams','venues','referee_roles','referee_eligibility','fixtures','fixture_sync_logs','appointments','appointment_history','match_officials','match_context_snapshots','performance_checkins','performance_sessions','physical_tests','readiness_scores','wellness_logs','clips','ifab_library_documents','institutional_clips','institutional_leads','notification_preferences','notification_tokens','coach_runs','coach_evidence','ai_usage_ledger','platform_audit_logs','institution_audit_logs','coach_rate_limit_buckets']::text[])),
 svc as (select * from pg_catalog.pg_roles where rolname='service_role'),
 relations as (select c.* from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace
   where n.nspname='public' and c.relname in ('user_profiles','match_preparations','post_match_reviews','psychology_checkins','psychology_wellbeing_assessments','psychology_exercise_sessions','attempts','exam_results','rules_exam_results','notification_events','user_global_roles','user_subscriptions','referee_exam_sessions','capabilities','capability_overrides','plan_capabilities','institutions','institution_subscriptions','institution_permissions','institution_roles','institution_role_permissions','institution_membership_permission_overrides','institution_memberships','institution_membership_roles','institution_groups','institution_group_memberships','institution_cohorts','institution_contents','institution_content_assignments','institution_assessments','institution_assessment_items','institution_assessment_assignments','institution_assessment_sessions','institution_assessment_history','institution_notification_campaigns','institution_notification_recipients','institution_demo_sessions','institution_data_consents','countries','associations','competitions','competition_seasons','competition_categories','teams','venues','referee_roles','referee_eligibility','fixtures','fixture_sync_logs','appointments','appointment_history','match_officials','match_context_snapshots','performance_checkins','performance_sessions','physical_tests','readiness_scores','wellness_logs','clips','ifab_library_documents','institutional_clips','institutional_leads','notification_preferences','notification_tokens','coach_runs','coach_evidence','ai_usage_ledger','platform_audit_logs','institution_audit_logs','coach_rate_limit_buckets') and c.relkind in ('r','p')),
 cols as (select c.relname as table_name,c.oid as table_oid,a.* from relations c join pg_catalog.pg_attribute a on a.attrelid=c.oid
   where a.attnum>0 and not a.attisdropped),
 ta as (select c.relname as table_name,a.* from relations c cross join lateral pg_catalog.aclexplode(coalesce(c.relacl,pg_catalog.acldefault('r',c.relowner))) a),
 ca as (select c.table_name,c.attname,a.* from cols c cross join lateral pg_catalog.aclexplode(c.attacl) a),
 funcs as (select p.*,n.nspname,l.lanname,n.nspname||'.'||p.proname||'('||pg_catalog.oidvectortypes(p.proargtypes)||')' as signature
   from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace join pg_catalog.pg_language l on l.oid=p.prolang
   where n.nspname='public' and p.proname in ('submit_referee_exam','submit_canonical_training_attempt','submit_canonical_communication_feedback','admin_set_canonical_user_plan','admin_set_canonical_global_role','consume_coach_rate_limit','accept_canonical_institution_invitation')),
 fa as (select f.signature,a.* from funcs f cross join lateral pg_catalog.aclexplode(coalesce(f.proacl,pg_catalog.acldefault('f',f.proowner))) a)
 select jsonb_build_object(
 'serverVersion',current_setting('server_version_num')::integer,
 'databaseOwner',(select pg_get_userbyid(datdba) from pg_catalog.pg_database where datname=current_database()),
 'catalogCounts',jsonb_build_object('roles',(select count(*) from pg_catalog.pg_roles),'memberships',(select count(*) from pg_catalog.pg_auth_members),
   'tableAcls',(select count(*) from ta),'columnAcls',(select count(*) from ca where table_name in ('user_profiles','match_preparations','post_match_reviews','psychology_checkins','psychology_wellbeing_assessments','psychology_exercise_sessions','attempts','exam_results','rules_exam_results','notification_events','user_global_roles','user_subscriptions','referee_exam_sessions')),
   'functionAcls',(select count(*) from fa)),
 'roleAttributes',(select jsonb_agg(jsonb_build_object('name',r.rolname,'rolsuper',r.rolsuper,'rolinherit',r.rolinherit,
   'rolcreaterole',r.rolcreaterole,'rolcreatedb',r.rolcreatedb,'rolcanlogin',r.rolcanlogin,'rolreplication',r.rolreplication,
   'rolbypassrls',r.rolbypassrls,'rolconnlimit',r.rolconnlimit,'serviceRoleMember',pg_has_role(s.oid,r.oid,'MEMBER'),
   'serviceRoleInherits',pg_has_role(s.oid,r.oid,'USAGE'),'serviceRoleCanSet',pg_has_role(s.oid,r.oid,'SET')) order by r.rolname)
   from pg_catalog.pg_roles r cross join svc s),
 'roleMemberships',(select coalesce(jsonb_agg(jsonb_build_object('member',pg_get_userbyid(m.member),'role',pg_get_userbyid(m.roleid),
   'grantor',pg_get_userbyid(m.grantor),'adminOption',m.admin_option,'inheritOption',m.inherit_option,'setOption',m.set_option)
   order by m.member,m.roleid,m.grantor),'[]'::jsonb) from pg_catalog.pg_auth_members m),
 'tables',(select jsonb_agg(jsonb_build_object('schema','public','table',e.table_name,'exists',c.oid is not null,
   'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force',c.relforcerowsecurity,'rawAcl',c.relacl,
   'aclOrigin',case when c.oid is null then 'ABSENT' when c.relacl is null then 'DEFAULT_OWNER_ACL' else 'EXPLICIT_ACL' end)
   order by e.table_name) from expected e left join relations c on c.relname=e.table_name),
 'tableAcls',(select coalesce(jsonb_agg(jsonb_build_object('schema','public','table',table_name,
   'grantee',case when grantee=0 then 'PUBLIC' else pg_get_userbyid(grantee) end,'grantor',pg_get_userbyid(grantor),
   'privilege',privilege_type,'grantable',is_grantable) order by table_name,grantee,grantor,privilege_type),'[]'::jsonb) from ta),
 'effectiveTablePrivileges',(select jsonb_agg(jsonb_build_object('schema','public','table',e.table_name,'role','service_role',
   'privilege',p.privilege,'granted',case when c.oid is null then null else pg_catalog.has_table_privilege(s.oid,c.oid,p.privilege) end)
   order by e.table_name,p.privilege) from expected e left join relations c on c.relname=e.table_name cross join svc s
   cross join unnest(array['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER','MAINTAIN']::text[]) p(privilege)),
 'columns',(select coalesce(jsonb_agg(jsonb_build_object('schema','public','table',table_name,'column',attname,'rawAcl',attacl)
   order by table_name,attnum),'[]'::jsonb) from cols where table_name in ('user_profiles','match_preparations','post_match_reviews','psychology_checkins','psychology_wellbeing_assessments','psychology_exercise_sessions','attempts','exam_results','rules_exam_results','notification_events','user_global_roles','user_subscriptions','referee_exam_sessions')),
 'columnAcls',(select coalesce(jsonb_agg(jsonb_build_object('schema','public','table',table_name,'column',attname,
   'grantee',case when grantee=0 then 'PUBLIC' else pg_get_userbyid(grantee) end,'grantor',pg_get_userbyid(grantor),
   'privilege',privilege_type,'grantable',is_grantable) order by table_name,attname,grantee,grantor,privilege_type),'[]'::jsonb)
   from ca where table_name in ('user_profiles','match_preparations','post_match_reviews','psychology_checkins','psychology_wellbeing_assessments','psychology_exercise_sessions','attempts','exam_results','rules_exam_results','notification_events','user_global_roles','user_subscriptions','referee_exam_sessions')),
 'effectiveColumnPrivileges',(select coalesce(jsonb_agg(jsonb_build_object('schema','public','table',c.table_name,'column',c.attname,
   'role','service_role','privilege',p.privilege,'granted',pg_catalog.has_column_privilege(s.oid,c.table_oid,c.attnum,p.privilege))
   order by c.table_name,c.attnum,p.privilege),'[]'::jsonb) from cols c cross join svc s
   cross join unnest(array['SELECT','INSERT','UPDATE','REFERENCES']::text[]) p(privilege) where c.table_name in ('user_profiles','match_preparations','post_match_reviews','psychology_checkins','psychology_wellbeing_assessments','psychology_exercise_sessions','attempts','exam_results','rules_exam_results','notification_events','user_global_roles','user_subscriptions','referee_exam_sessions')),
 'relevantFunctions',(select jsonb_agg(jsonb_build_object('name',e.name,'exists',f.oid is not null,'signature',f.signature,
   'owner',pg_get_userbyid(f.proowner),'language',f.lanname,'security_definer',f.prosecdef,'volatility',f.provolatile,
   'strict',f.proisstrict,'leakproof',f.proleakproof,'configuration',f.proconfig,'sourceHash',md5(f.prosrc),
   'rawAcl',f.proacl,'serviceRoleExecute',case when f.oid is null then null else pg_catalog.has_function_privilege(s.oid,f.oid,'EXECUTE') end)
   order by e.name,f.signature) from unnest(array['submit_referee_exam','submit_canonical_training_attempt','submit_canonical_communication_feedback','admin_set_canonical_user_plan','admin_set_canonical_global_role','consume_coach_rate_limit','accept_canonical_institution_invitation']::text[]) e(name)
   left join funcs f on f.proname=e.name cross join svc s),
 'functionExecuteAcls',(select coalesce(jsonb_agg(jsonb_build_object('signature',signature,
   'grantee',case when grantee=0 then 'PUBLIC' else pg_get_userbyid(grantee) end,'grantor',pg_get_userbyid(grantor),
   'privilege',privilege_type,'grantable',is_grantable) order by signature,grantee,grantor),'[]'::jsonb) from fa)
 )
) into service;
  if (select coalesce(jsonb_agg(x order by x::text),'[]'::jsonb) from jsonb_array_elements(browser->'tableAcls') x) is distinct from (select coalesce(jsonb_agg(x order by x::text),'[]'::jsonb) from jsonb_array_elements('[{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"attempts","privilege":"DELETE"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"attempts","privilege":"INSERT"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"attempts","privilege":"MAINTAIN"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"attempts","privilege":"REFERENCES"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"attempts","privilege":"SELECT"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"attempts","privilege":"TRIGGER"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"attempts","privilege":"TRUNCATE"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"attempts","privilege":"UPDATE"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"exam_results","privilege":"DELETE"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"exam_results","privilege":"INSERT"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"exam_results","privilege":"MAINTAIN"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"exam_results","privilege":"REFERENCES"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"exam_results","privilege":"SELECT"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"exam_results","privilege":"TRIGGER"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"exam_results","privilege":"TRUNCATE"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"exam_results","privilege":"UPDATE"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"match_preparations","privilege":"DELETE"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"match_preparations","privilege":"INSERT"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"match_preparations","privilege":"MAINTAIN"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"match_preparations","privilege":"REFERENCES"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"match_preparations","privilege":"SELECT"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"match_preparations","privilege":"TRIGGER"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"match_preparations","privilege":"TRUNCATE"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"match_preparations","privilege":"UPDATE"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"notification_events","privilege":"DELETE"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"notification_events","privilege":"INSERT"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"notification_events","privilege":"MAINTAIN"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"notification_events","privilege":"REFERENCES"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"notification_events","privilege":"SELECT"},{"grantable":false,"grantee":"postgres","grantor":"postgres","schema":"public","table":"notificatio